package main

import (
	"crypto/elliptic"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/asn1"
	"encoding/hex"
	"encoding/pem"
)

func pathVectors(m material) suite {
	rootPem, _ := pem.Decode(m.root)
	root := must(x509.ParseCertificate(rootPem.Bytes))
	rootKey := fixedKey("root", elliptic.P256())
	interKey := fixedKey("intermediate", elliptic.P256())
	otherKey := fixedKey("alternate root", elliptic.P256())
	alternate := pemCert(certificate(10, "SGX fixture root", otherKey, nil, nil, true, 1))
	zeroDer := certificate(11, "SGX fixture root", rootKey, nil, nil, true, 0)
	zero := must(x509.ParseCertificate(zeroDer))
	direct := pemCert(certificate(12, "SGX fixture leaf", m.leaf, zero, rootKey, false, -1))
	critical := func(cert *x509.Certificate) {
		cert.ExtraExtensions = []pkix.Extension{{Id: asn1.ObjectIdentifier{1, 2, 3, 4}, Critical: true, Value: []byte{5, 0}}}
	}
	interPem, _ := pem.Decode(m.intermediatePem)
	inter := must(x509.ParseCertificate(interPem.Bytes))
	badLeaf := pemCert(editedCertificate(13, "SGX fixture leaf", m.leaf, inter, interKey, false, -1, critical))
	badRoot := pemCert(editedCertificate(14, "SGX fixture root", rootKey, nil, nil, true, 1, critical))
	badUsage := pemCert(editedCertificate(15, "SGX fixture intermediate", interKey, root, rootKey, true, 0, func(cert *x509.Certificate) {
		cert.KeyUsage = x509.KeyUsageDigitalSignature
	}))
	nonCa := pemCert(certificate(16, "SGX fixture intermediate", interKey, root, rootKey, false, -1))
	impostor := pemCert(certificate(17, "SGX fixture intermediate", otherKey, root, rootKey, true, 0))
	brokenLeaf := append([]byte(nil), m.leafDer...)
	brokenLeaf[len(brokenLeaf)-1] ^= 1
	file := suite{Primitive: "sgx-pck-path", Source: "Fixed P-256 paths generated by Go crypto/x509; RFC 5280 pathLen and critical-extension rules"}
	add := func(id string, chain, anchors []byte, expected string) {
		file.Vectors = append(file.Vectors, vector{ID: id, Op: "sgx-pck", Hex: hex.EncodeToString(chain), Anchors: hex.EncodeToString(anchors), Now: 1735689600000, Expected: expected})
	}
	concat := func(a, b []byte) []byte { return append(append([]byte(nil), a...), b...) }
	add("included-root", concat(m.chain, m.root), m.root, "ok certs=3")
	add("pinned-intermediate", m.chain, m.intermediatePem, "ok certs=2")
	add("alternate-anchor-first", m.chain, concat(alternate, m.root), "ok certs=2")
	add("alternate-anchor-last", m.chain, concat(m.root, alternate), "ok certs=2")
	add("pathlen-zero-reject", m.chain, pemCert(zeroDer), "error:pck-chain-mismatch")
	add("pathlen-zero-direct", concat(direct, pemCert(zeroDer)), pemCert(zeroDer), "ok certs=2")
	add("critical-leaf", concat(badLeaf, m.intermediatePem), m.root, "error:bad-pck-chain")
	add("critical-anchor", m.chain, badRoot, "error:bad-pck-chain")
	add("issuer-key-usage", concat(pemCert(m.leafDer), badUsage), m.root, "error:pck-chain-mismatch")
	add("issuer-not-ca", concat(pemCert(m.leafDer), nonCa), m.root, "error:pck-chain-mismatch")
	full := concat(m.chain, m.root)
	add("full-chain-pin-intermediate", full, m.intermediatePem, "ok certs=3")
	add("full-chain-pin-both", full, concat(m.intermediatePem, m.root), "ok certs=3")
	add("full-chain-pin-unrelated", full, m.wrongRoot, "error:pck-chain-mismatch")
	add("full-chain-pin-impostor", full, impostor, "error:pck-chain-mismatch")
	add("pinned-intermediate-broken-leaf", concat(concat(pemCert(brokenLeaf), m.intermediatePem), m.root), m.intermediatePem, "error:pck-chain-mismatch")
	add("pinned-intermediate-ignores-rest", concat(m.chain, m.wrongRoot), m.intermediatePem, "ok certs=3")
	return file
}
